// Contrato de entrada (lo manda lib/adapters/bridge.ts):
//   { filters: SearchFilters, portals: string[] }
//
// filters = { make, model, yearFrom, yearTo, priceFrom, priceTo, kmTo,
//             powerFrom, fuel, gearbox, seller, countries[], sort }

const body = $input.first().json.body ?? $input.first().json;
const f = body.filters ?? {};

return [{
  json: {
    filters: f,
    portals: body.portals ?? [],
    query: [f.make, f.model].filter(Boolean).join(' ').trim(),
    priceFrom: f.priceFrom ?? null,
    priceTo: f.priceTo ?? null,
    kmTo: f.kmTo ?? null,
    yearFrom: f.yearFrom ?? null,
    countries: f.countries ?? []
  }
}];

// ─────────────────────────────────────────────────────────────
// AQUI ES DONDE ENCHUFAS TU FUENTE
// ─────────────────────────────────────────────────────────────
// Sustituye este nodo por lo que tengas: un feed de un concesionario
// con el que trabajes, una API con credenciales, tu propia base de
// datos de anuncios o un servicio de scraping que hayas contratado.
//
// Lo unico que tiene que devolver es un array `listings` con esta forma
// (los campos opcionales pueden ir vacios, pero cuantos mas, mejor
// ordena la app):
//
//   {
//     id:       'string unico',
//     title:    'BMW 320d xDrive 190 CV',
//     price:    14500,          // euros, sin puntos
//     year:     2019,
//     km:       95000,
//     co2:      128,            // g/km WLTP -> decide el impuesto
//     power:    190,            // CV
//     fuel:     'diesel',       // gasolina|diesel|hibrido|phev|electrico|glp|gnc
//     gearbox:  'automatico',   // manual|automatico
//     country:  'DE',           // DE|FR|IT|NL|BE|AT|PT|PL|LU|ES
//     city:     'Munich',
//     seller:   'particular',   // particular|profesional
//     url:      'https://...',
//     image:    'https://...',
//     sourceName: 'Nombre que se ve en la tarjeta'
//   }

const listings = [];

return [{ json: { listings } }];
